"""Advanced-chart statistics against (1) scipy/numpy reference values recorded in tests/fixtures/advanced/stats_reference.json (generated by
gen_stats_reference.py in a throwaway virtualenv; scipy is never a dependency) and (2) an independent exact computation with
fractions.Fraction written here, so no figure rests on one code path."""

import json
import math
from decimal import Decimal, getcontext
from fractions import Fraction
from pathlib import Path

import pytest

from finlit.advanced import stats as S

REF = json.loads((Path(__file__).parent / "fixtures" / "advanced" / "stats_reference.json").read_text())
DATA = REF["datasets"]
getcontext().prec = 50


def run(name):
    d = DATA[name]
    return S.analyse([(x, y, i) for i, (x, y) in enumerate(zip(d["x"], d["y"]))]), d


def rel(a, b, tol=1e-9):
    return abs(a - b) <= tol * max(1.0, abs(b))


# ------------------------------------------------------------ independent exact path (Fractions)
def exact(xs, ys):
    X = [Fraction(str(v)) for v in xs]
    Y = [Fraction(str(v)) for v in ys]
    n = len(X)
    xb, yb = sum(X) / n, sum(Y) / n
    sxx = sum((x - xb) ** 2 for x in X)
    syy = sum((y - yb) ** 2 for y in Y)
    sxy = sum((x - xb) * (y - yb) for x, y in zip(X, Y))
    b = sxy / sxx
    a = yb - b * xb
    r2 = sxy * sxy / (sxx * syy)
    rr = float(Decimal(r2.numerator).sqrt() / Decimal(r2.denominator).sqrt()) * (1 if sxy > 0 else -1)
    slopes = sorted((Y[j] - Y[i]) / (X[j] - X[i]) for i in range(n) for j in range(i + 1, n) if X[j] != X[i])
    m = len(slopes)
    tsb = slopes[m // 2] if m % 2 else (slopes[m // 2 - 1] + slopes[m // 2]) / 2
    resid = sorted(y - tsb * x for x, y in zip(X, Y))
    tsa = resid[n // 2] if n % 2 else (resid[n // 2 - 1] + resid[n // 2]) / 2

    def rk(v):
        order = sorted(range(n), key=lambda i: v[i])
        out = [Fraction(0)] * n
        i = 0
        while i < n:
            j = i
            while j + 1 < n and v[order[j + 1]] == v[order[i]]:
                j += 1
            for k in range(i, j + 1):
                out[order[k]] = Fraction(i + j, 2) + 1
            i = j + 1
        return out
    rx, ry = rk(X), rk(Y)
    mx, my = sum(rx) / n, sum(ry) / n
    num = sum((p - mx) * (q - my) for p, q in zip(rx, ry))
    den2 = sum((p - mx) ** 2 for p in rx) * sum((q - my) ** 2 for q in ry)
    rho2 = num * num / den2
    rho = float(Decimal(rho2.numerator).sqrt() / Decimal(rho2.denominator).sqrt()) * (1 if num > 0 else -1 if num < 0 else 0)
    return {"b": float(b), "a": float(a), "r": rr, "r2": float(r2), "ts": (float(tsb), float(tsa)), "rho": rho}


NAMES = [k for k in DATA]


@pytest.mark.parametrize("name", NAMES)
def test_against_scipy_and_exact(name):
    st, d = run(name)
    ex = exact(d["x"], d["y"])
    if name == "exact_line":
        assert st["pearson"]["r"] == 1.0 and st["pearson"]["p"] == 0.0 and st["ols"]["se"] == 0.0
        assert all(b["lo"] == b["hi"] for b in st["band"])            # zero-width band
        assert st["decision"]["line"] in ("ols",)
        return
    assert rel(st["pearson"]["r"], d["r"]) and rel(st["pearson"]["r"], ex["r"])
    assert rel(st["pearson"]["r2"], ex["r2"])
    assert rel(st["ols"]["slope"], d["slope"]) and rel(st["ols"]["slope"], ex["b"])
    assert rel(st["ols"]["intercept"], d["intercept"]) and rel(st["ols"]["intercept"], ex["a"])
    assert rel(st["ols"]["se"], d["se_slope"])
    assert rel(st["pearson"]["p"], d["p"], 1e-8)                      # incomplete-beta continued fraction vs scipy
    assert rel(st["spearman"]["rho"], d["rho"]) and rel(st["spearman"]["rho"], ex["rho"])
    if d["n"] >= 10:
        assert rel(st["spearman"]["p"], d["rho_p"], 1e-8)
    assert rel(st["theilSen"]["slope"], d["ts_slope"]) and rel(st["theilSen"]["slope"], ex["ts"][0])
    assert rel(st["theilSen"]["intercept"], d["ts_intercept"]) and rel(st["theilSen"]["intercept"], ex["ts"][1])
    assert rel(st["ols"]["tCrit"], d["t_crit"], 1e-10)
    assert st["pearson"]["ci"][0] == pytest.approx(d["fisher_ci"][0], rel=1e-9) and st["pearson"]["ci"][1] == pytest.approx(d["fisher_ci"][1], rel=1e-9)
    if st["curvature"] is not None:
        assert rel(st["curvature"]["c2"], d["c2"], 1e-7) and rel(st["curvature"]["dR2"], d["dR2"], 1e-7)
        assert rel(st["curvature"]["p"], d["c2_p"], 1e-6) or (st["curvature"]["p"] < 1e-15 and d["c2_p"] < 1e-15)
    assert st["influence"]["max"]["label"] == d["cook_max_index"]
    if st["band"]:
        assert rel(st["band"][0]["lo"], d["band_at_min"][0]) and rel(st["band"][0]["hi"], d["band_at_min"][1])


def test_anscombe_published_values_and_decisions():
    st, _ = run("anscombe_I")
    assert round(st["pearson"]["r"], 6) == 0.816421 and round(st["ols"]["slope"], 6) == 0.500091 and round(st["ols"]["intercept"], 6) == 3.000091
    assert round(st["pearson"]["r2"], 6) == 0.666542 and round(st["pearson"]["t"], 6) == 4.241455 and round(st["pearson"]["p"], 7) == 0.0021696
    assert round(st["spearman"]["rho"], 6) == 0.818182 and (round(st["theilSen"]["slope"], 6), round(st["theilSen"]["intercept"], 6)) == (0.501667, 2.936667)
    assert st["decision"]["rule"] == "ok" and st["decision"]["line"] == "ols"
    st, _ = run("anscombe_II")
    assert round(st["pearson"]["r"], 6) == 0.816237 and round(st["spearman"]["rho"], 6) == 0.690909 and st["decision"]["rule"] == "curved"
    st, _ = run("anscombe_III")
    assert round(st["pearson"]["r"], 6) == 0.816287 and round(st["ols"]["slope"], 6) == 0.499727 and round(st["spearman"]["rho"], 6) == 0.990909
    assert (round(st["theilSen"]["slope"], 6), round(st["theilSen"]["intercept"], 6)) == (0.345556, 4.004444)
    assert st["decision"]["rule"] == "pulled" and st["decision"]["line"] == "ols_ts" and st["tsLine"] is not None
    st, _ = run("anscombe_IV")
    assert round(st["pearson"]["r"], 6) == 0.816521 and st["spearman"]["rho"] == 0.5
    assert st["decision"]["rule"] == "one_company" and st["influence"]["max"]["label"] == 7 and st["influence"]["without"] is None


def test_t_distribution():
    for df, v in REF["t_crit"].items():
        assert rel(S.t_crit(float(df)), v, 1e-10), df
    assert round(S.t_crit(9), 6) == 2.262157 and round(S.t_crit(30), 6) == 2.042272 and round(S.t_crit(1000), 6) == 1.962339
    for t, df, p in REF["t_p"]:
        assert rel(S.t_two_sided_p(t, df), p, 1e-9) or abs(S.t_two_sided_p(t, df) - p) < 1e-300, (t, df)
    assert round(S.t_two_sided_p(2, 10), 6) == 0.073388 and round(S.t_two_sided_p(1, 5), 6) == 0.363217


def test_edge_cases():
    st = S.analyse([(float(i), 5.0, i) for i in range(12)])                   # constant y
    assert st["pearson"] is None and st["decision"]["rule"] == "no_spread" and st["line"] is None
    st = S.analyse([(1.0, 2.0, "a"), (2.0, 3.0, "b")])                          # n = 2
    assert st["decision"]["rule"] == "few" and st["pearson"] is None and st["theilSen"]["slope"] == 1.0
    st = S.analyse([(3.0, float(i), i) for i in range(15)])                    # constant x
    assert st["decision"]["rule"] == "no_spread" and st["theilSen"] is None
    assert S.analyse([]) is None
    assert S.ranks([3, 1, 3, 2, 3]) == [4.0, 1.0, 4.0, 2.0, 4.0]
    st, _ = run("noise_n25")
    assert st["decision"]["rule"] in ("not_significant", "weak")
    assert S.fmt_p(0.0004) == "< 0.001" and S.fmt_p(0.0123456) == "0.0123" and S.sig(0.0912345) == "0.0912"
    assert S.quantile7([1, 2, 3, 4], 0.5) == 2.5 and S.quantile7([1, 2, 3, 4, 5], 0.01) == pytest.approx(1.04)


def test_log_space_back_transform():
    pts = [(math.log10(10 ** (i / 4)), math.log10(3 * 10 ** (i / 4)), i) for i in range(20)]
    st = S.analyse(pts, back_x=lambda v: 10 ** v, back_y=lambda v: 10 ** v)
    assert st["line"]["x0"] == pytest.approx(1.0) and st["line"]["y0"] == pytest.approx(3.0)
    assert st["line"]["y1"] / st["line"]["x1"] == pytest.approx(3.0)


def test_deterministic_and_rounding():
    st1, _ = run("random_neg_n200")
    st2, _ = run("random_neg_n200")
    assert st1 == st2
    out = S.round_sig({"a": 0.123456789, "b": [1234567.891, float("inf")]})
    assert out == {"a": 0.123457, "b": [1234570.0, None]}
